import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.DpN-jjzu.js";const k=JSON.parse('{"title":"错误与兼容规范","description":"","frontmatter":{"editLink":true},"headers":[],"relativePath":"api/standards.md","filePath":"api/standards.md"}'),d={name:"api/standards.md"};function o(n,a,h,r,l,p){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="错误与兼容规范" tabindex="-1">错误与兼容规范 <a class="header-anchor" href="#错误与兼容规范" aria-label="Permalink to &quot;错误与兼容规范&quot;">​</a></h1><p>本文使用“必须”表示契约要求，“建议”表示接入建议。规则面向本站快照及文档发布；外部服务不受本站契约约束。</p><h2 id="数据与时间" tabindex="-1">数据与时间 <a class="header-anchor" href="#数据与时间" aria-label="Permalink to &quot;数据与时间&quot;">​</a></h2><ol><li>发布数据必须满足 <a href="site-data.schema.json">JSON Schema</a> 和<a href="./models.html">业务约束</a>，不可把类型错误、缺失字段或非法日期当作成功。</li><li>对象不接受未知字段；<code>null</code> 表示明确未知，不能替换成 <code>0</code>、空字符串或当前时间。</li><li>时间戳必须是带时区的 RFC 3339 / ISO date-time。贡献日历的日期使用 <code>YYYY-MM-DD</code>，日期不能带时间。</li><li>Git 提交者时间、快照生成时间和 OJ 评测时间必须分别表达。本站没有 OJ 提交记录字段。</li><li><code>problemUrl</code> 可以指向比赛页或平台首页。不得将推导 URL 宣称为已验证的原题链接。</li></ol><h2 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>客户端处理</th></tr></thead><tbody><tr><td><code>200</code> 且符合契约</td><td>接受快照，显示 <code>generatedAt</code></td></tr><tr><td><code>200</code> 但 JSON 解析或校验失败</td><td>判为无效数据，不覆盖已验证缓存</td></tr><tr><td><code>304</code></td><td>使用已有缓存；无缓存则重新发起完整请求</td></tr><tr><td><code>404</code></td><td>检查完整 API 地址和发布状态；响应可能是 HTML</td></tr><tr><td><code>403</code> / <code>429</code> 或限流提示</td><td>读取服务给出的限流与重试信息，停止密集请求</td></tr><tr><td>网络超时 / <code>5xx</code></td><td>有上限地重试，保留旧数据并说明更新失败</td></tr></tbody></table><p>本站静态托管没有统一的 <code>{code,message}</code> 错误体，不能对所有错误响应无条件调用 <code>response.json()</code>。建议每次请求设置超时，对暂时性失败采用带抖动的退避并限制次数，不对固定的路径错误无限重试。</p><p>网站当前实现的超时只覆盖源码读取，快照和部分在线同步尚无统一超时；这些既有行为与这里给接入方的建议不同。</p><h2 id="兼容与变更" tabindex="-1">兼容与变更 <a class="header-anchor" href="#兼容与变更" aria-label="Permalink to &quot;兼容与变更&quot;">​</a></h2><p>当前契约为 <code>1.0.0</code>，版本维护在 OpenAPI <code>info.version</code> 和 schema 描述中。响应暂无版本字段。新增或删除字段、修改字段类型、可空性、枚举或语义时，必须同步更新 schema、参考文档、校验和版本说明；不能仅修改展示文字。</p><p>由于 <code>additionalProperties: false</code>，增加字段也会被旧严格校验器拒绝，应按不兼容变更处理并先提供迁移方案。修正文档笔误但不改变契约可使用补丁版本。未经实施的版本化 URL 或写接口只能写为未来方案，不可列为现有接口。</p><h2 id="校验命令" tabindex="-1">校验命令 <a class="header-anchor" href="#校验命令" aria-label="Permalink to &quot;校验命令&quot;">​</a></h2><p>在 <code>docs/project-guide</code> 的仓库根目录：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:api</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>检查器校验 OpenAPI 文档、自包含的 JSON Schema 和当前 <code>origin/gh-pages</code> 中真实快照，并执行坏数据拒绝检查。构建从 schema 生成模型表，校验站内链接，再产出可部署文件。网络部署验证另行获取线上响应，以免把本地构建成功当成已经上线。</p><p>契约检查不证明全部原题链接可用、源码正确或题库完整。当前已知漏收路径见<a href="./../pages.html">题库维护</a>。</p>`,16)])])}const F=e(d,[["render",o]]);export{k as __pageData,F as default};
